/**
 * Language writing direction
 */
declare type LanguageDirection = 'ltr' | 'rtl';

/**
 * Base event class: Event<T, D = void, R = void>.
 * @template T - Event type
 * @template D - Event data type
 * @template R - Result type returned to the dispatcher through `evt.sendResult(data)`
 */
declare class ChatUIEvent<T extends string, D = void, R = void> {
    /**
     * Event type
     */
    readonly type: T;
    /**
     * Tracks results returned to the dispatcher through `evt.sendResult(data)`.
     * - false: no result is awaited
     * - true: a result has been returned
     * - function: a result is pending
     */
    private _resolve;
    private _promise?;
    private _stopped;
    private _defaultPrevented;
    /**
     * Event data
     */
    readonly data: D;
    /**
     * @protected Internal use only
     */
    constructor(
    /**
     * Event type
     */
    type: T, data?: D);
    /**
     * @returns Whether event propagation was stopped
     */
    isImmediatePropagationStopped(): boolean;
    /**
     * Stop subsequent listeners for this event type.
     */
    stopImmediatePropagation(): void;
    /**
     * @returns Whether the default behavior was prevented
     */
    isDefaultPrevented(): boolean;
    /**
     * Prevent the event's default behavior.
     * @description This does not stop propagation, and not every event has a default behavior.
     */
    preventDefault(): void;
    /**
     * Send result data to the event dispatcher.
     * @param data
     */
    sendResult(data: R): void;
    /**
     * Wait for a listener to return result data.
     * @returns
     */
    awaitResult(): Promise<R>;
    /**
     * Clone the event instance.
     * @param ignoreResult - Whether to ignore returned data. When true, the clone cannot return data through `evt.sendResult(data)`.
     * @returns
     */
    clone(): ChatUIEvent<T, D, R>;
}

declare class EventDispatcher<T> {
    private _listeners;
    addEventListener<K extends keyof T>(type: K | string, listener: (evt: T[K]) => void, target?: any): void;
    onceEventListener<K extends keyof T>(type: K | string, listener: (evt: T[K]) => void, target?: any): void;
    removeEventListener<K extends keyof T>(type: K | string, listener: (evt: T[K]) => void, target?: any): void;
    private _removeListenerItem;
    removeEventListeners(type: string | keyof T): void;
    removeAllEventListeners(): void;
    /**
     * Dispatch an event and run listeners synchronously or asynchronously.
     * @description
     * When `defer` is `true`, listeners run in the next event loop instead of immediately.
     * @param event - Event object
     * @param defer - Run listeners asynchronously; defaults to `true`
     */
    dispatchEvent<K extends keyof T>(event: T[K], defer?: boolean): void;
    private _handleDispatchEvent;
}

/**
 * Feature toggle commands for controlling ChatUI behavior
 * @description Use these commands with setCommandSwitch() to enable/disable specific features
 * @example
 * ```typescript
 * // Enable message read status display
 * app.setCommandSwitch(ChatUICommand.SHOW_MESSAGE_STATE, true);
 *
 * // Enable @all functionality
 * app.setCommandSwitch(ChatUICommand.AT_ALL, true);
 * ```
 */
declare enum ChatUICommand {
    /**
     * Show connection status in the channel list
     * - true - Show (Default)
     * - false - Hide
     */
    SHOW_CONNECTION_STATUS_IN_CHANNEL_LIST = "SHOW_CONNECTION_STATUS_IN_CHANNEL_LIST",
    /**
     * Show message read and sent status
     * - true - Enable (Default)
     * - false - Disable, only show sending and failed status
     */
    SHOW_MESSAGE_STATE = "SHOW_MESSAGE_STATE",
    /**
     * '@all' functionality toggle
     * - true - Enable (Default)
     * - false - Disable
     */
    MENTION_ALL = "MENTION_ALL",
    /**
     * Automatically @ the sender when quoting or replying to a message
     * - true - Enable
     * - false - Disable (Default)
     */
    PROMPT_SENDER_WHEN_QUOTE_MESSAGE = "PROMPT_SENDER_WHEN_QUOTE_MESSAGE",
    /**
     * Delete local and remote messages when deleting a channel
     * - true - Enable
     * - false - Disable (Default)
     */
    DELETE_MESSAGES_WHILE_DELETE_CHANNEL = "DELETE_MESSAGES_WHILE_DELETE_CHANNEL",
    /**
     * Message reaction feature toggle
     * - true - Enable
     * - false - Disable (Default)
     */
    MESSAGE_REACTION_ENABLED = "MESSAGE_REACTION_ENABLED",
    /**
     * Show reacting-user names in message reaction chips
     * - true - Show names
     * - false - Show counts (Default)
     *
     * Requires MESSAGE_REACTION_ENABLED.
     */
    SHOW_MESSAGE_REACT_USERS = "SHOW_MESSAGE_REACT_USERS",
    /**
     * Message editing feature toggle
     * - true - Enable
     * - false - Disable (Default)
     */
    MESSAGE_EDIT_ENABLED = "MESSAGE_EDIT_ENABLED"
}

/** Reaction summary stored on a ChatUI message. */
interface ChatUIMessageReaction extends Omit<MessageReaction, 'users'> {
    /** At most ten unique user IDs, with the current user first when present. */
    users: string[];
}
/** Message editing state stored on a chat message model. */
declare enum ChatUIMessageEditStatus {
    /** An edit request is currently in progress. */
    UPDATING = "UPDATING",
    /** The last edit request failed and can be retried or reopened. */
    FAILED = "FAILED",
    /** The message has been updated and has an SDK update timestamp. */
    SUCCESS = "SUCCESS"
}
/**
 * Message model representing a single message in a conversation
 * @description Wraps the SDK's Message object with additional UI-specific properties
 */
declare class ChatUIMessageModel<T extends Record<string, any> = Record<string, any>> {
    readonly message: Message<T>;
    /**
     * Send transaction ID. Locally created messages include this ID to match related events.
     */
    transactionId?: number;
    /**
     * Upload progress
     * * 100 indicates completion
     * * -1 indicates failure
     */
    progress?: number;
    /**
     * File awaiting upload
     */
    file?: File;
    readReceiptInfo?: MessageReadReceiptInfo;
    /** Message reaction summaries used by the UI. */
    reactions: ChatUIMessageReaction[];
    /** Current in-memory message edit state. */
    editStatus?: ChatUIMessageEditStatus;
    /** In-memory edit draft. This is independent from the channel draft. */
    editDraft?: string;
    /** SDK update timestamp recorded for a successful edit. */
    editTimestamp?: number;
    /**
     * Constructor for creating a message model, internal use only
     * @private Internal use only
     * @hidden
     */
    constructor(message: Message);
    get messageId(): string;
    set messageId(id: string);
    get sentTime(): number;
    set sentTime(time: number);
    get direction(): MessageDirection;
    set direction(direction: MessageDirection);
    get content(): T;
    get messageType(): string;
    get isStatusMessage(): boolean;
    get senderUserId(): string;
    set senderUserId(userId: string);
    get channelIdentifier(): ChannelIdentifier;
    get channelType(): _nexconn_chat.ChannelType;
    get isPersisted(): boolean;
    get isCounted(): boolean;
    get sentStatus(): SentStatus;
    set sentStatus(status: SentStatus);
    get clientId(): number;
    set clientId(id: number);
    get sentReceipt(): boolean;
    set sentReceipt(value: boolean);
    get needReceipt(): boolean;
    clone(): ChatUIMessageModel;
    isEqual(message: ChatUIMessageModel): boolean;
}

/** Aggregated mention type for group channels. */
declare enum ChatUIMentionedType {
    /**
     * No mentions
     */
    NONE = 0,
    /**
     * Someone mentioned everyone in the group
     */
    AT_ALL = 1,
    /**
     * Someone mentioned the current user in the group
     */
    AT_ME = 2
}

/**
 * Channel model for a single entry in the channel list
 * @description Holds display and state data for that channel
 */
declare class ChatUIChannelModel {
    readonly channelIdentifier: ChannelIdentifier;
    /**
     * Constructor for creating a channel model, internal use only
     * @protected Internal use only
     */
    constructor(channelIdentifier: ChannelIdentifier);
    get channelId(): string;
    get channelType(): ChannelType;
    name: string;
    avatarUrl: string;
    draft: string;
    /** Message ID whose inline edit control is currently visible, if any. */
    updatingMessageUId?: string;
    latestMessage: null | ChatUIMessageModel;
    isPinned: boolean;
    noDisturbLevel: ChannelNoDisturbLevel;
    unreadCount: number;
    updateTime: number;
    /** Online status. `false` when display is disabled, no query hook is configured, or the channel is not direct. */
    online: boolean;
    /** Group member count. Always 0 for direct channels. */
    memberCount: number;
    /** Aggregated mention type for group channels. */
    mentionedType: ChatUIMentionedType;
    clone(): ChatUIChannelModel;
}

/**
 * Channel panel extension configuration
 * @description Defines a custom button/feature in the channel detail panel header
 * @example
 * ```typescript
 * const extension: ChannelPanelExtension = {
 *   id: 'video-call',
 *   icon: 'https://example.com/video-icon.svg',
 *   filter: (model) => model.channelType === ChannelType.PRIVATE
 * };
 * ```
 */
declare type ChannelPanelExtension = {
    /**
     * Extension ID, defined by the application
     */
    id: string;
    /**
     * Icon URL for the extension button
     */
    icon: string;
    /**
     * Filter function to control which channels show this extension
     * @param model - Channel model
     * @returns true to show, false to hide. Defaults to showing on all channels if not provided.
     */
    filter?: (model: ChatUIChannelModel) => boolean;
};
/**
 * Push notification configuration hook
 * @description Function to customize push notification content before sending a message
 * @param message - The message being sent
 * @returns Push configuration object
 * @example
 * ```typescript
 * const hook: PushConfigHook = (message) => ({
 *   pushTitle: `New message from ${message.senderUserId}`,
 *   pushContent: message.content?.text || '[Message]',
 *   pushData: JSON.stringify({ messageId: message.messageId })
 * });
 * ```
 */
declare type PushConfigHook = (message: ChatUIMessageModel) => PushConfig;

/**
 * Custom element class
 */
declare type CustomElementClass<T extends HTMLElement = HTMLElement> = new (...args: any[]) => T;
/**
 * Custom message component
 * @description Defines the Web Component tag and class for a custom message type
 */
interface CustomMessageComponent {
    /**
     * Custom element tag name for the message component
     */
    tagName: string;
    /**
     * Web Component class for the custom message element
     */
    elementClass: CustomElementClass;
    /**
     * Disables the bubble's standard content inset when the component owns its outer spacing.
     */
    disableDefaultBubblePadding?: boolean;
}
/**
 * Custom message registration configuration
 * @description Extends the SDK's CustomMessageRegistration with ChatUI-specific display options
 * @example
 * ```typescript
 * class GiftMessageElement extends HTMLElement {
 *   // ...
 * }
 *
 * const registration: ChatUICustomMessageRegistration = {
 *   messageType: 'custom:gift',
 *   isPersisted: true,
 *   isCounted: true,
 *   digest: (message, language) => {
 *     return language === 'en_US' ? '[Gift]' : '[Localized gift]';
 *   },
 *   component: {
 *     tagName: 'gift-message',
 *     elementClass: GiftMessageElement
 *   }
 * };
 * ```
 */
interface ChatUICustomMessageRegistration extends CustomMessageRegistration {
    /**
     * Custom digest function to generate a summary text for the channel list
     * @param message - The message model
     * @param language - Current language code (e.g., 'en_US')
     * @returns Digest text displayed in the channel list
     */
    digest?: (message: ChatUIMessageModel, language: string) => string;
    /**
     * Custom Web Component to render this message type in the chat panel
     */
    component?: CustomMessageComponent;
}

